import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import { CartProvider } from './context/CartContext';

import Navbar from './components/common/Navbar';
import Footer from './components/common/Footer';

import Home from './pages/marketplace/Home';
import Products from './pages/marketplace/Products';
import ProductDetail from './pages/marketplace/ProductDetail';
// Optional pages — some files may be empty placeholders; provide lightweight fallbacks
const Cart = React.lazy(() => import('./pages/marketplace/Cart').catch(() => ({ default: () => <div style={{padding:40}}>Cart page not implemented</div> })));
const CustomerLogin = React.lazy(() => import('./pages/auth/CustomerLogin').catch(() => ({ default: () => <div style={{padding:40}}>Login page not implemented</div> })));
const VendorLogin = React.lazy(() => import('./pages/auth/VendorLogin').catch(() => ({ default: () => <div style={{padding:40}}>Vendor login not implemented</div> })));
const VendorRegister = React.lazy(() => import('./pages/auth/VendorRegister').catch(() => ({ default: () => <div style={{padding:40}}>Vendor register not implemented</div> })));
const Profile = React.lazy(() => import('./pages/marketplace/Profile').catch(() => ({ default: () => <div style={{padding:40}}>Profile page not implemented</div> })));
const Checkout = React.lazy(() => import('./pages/marketplace/Checkout').catch(() => ({ default: () => <div style={{padding:40}}>Checkout page not implemented</div> })));
const OrderSuccess = React.lazy(() => import('./pages/marketplace/OrderSuccess').catch(() => ({ default: () => <div style={{padding:40}}>Order success page not implemented</div> })));

export default function App() {
  return (
    <AuthProvider>
      <CartProvider>
        <BrowserRouter>
          <Navbar />
          <main style={{ minHeight: '70vh' }}>
            <React.Suspense fallback={<div style={{padding:40}}>Loading...</div>}>
              <Routes>
                <Route path="/" element={<Home />} />
                <Route path="/products" element={<Products />} />
                <Route path="/products/:id" element={<ProductDetail />} />
                <Route path="/cart" element={<Cart />} />
                <Route path="/login" element={<CustomerLogin />} />
                <Route path="/vendor/login" element={<VendorLogin />} />
                <Route path="/vendor/register" element={<VendorRegister />} />
                <Route path="/account" element={<Profile />} />
                <Route path="/checkout" element={<Checkout />} />
                <Route path="/order-success" element={<OrderSuccess />} />
                <Route path="*" element={<div style={{padding:40}}>Page not found</div>} />
              </Routes>
            </React.Suspense>
          </main>
          <Footer />
        </BrowserRouter>
      </CartProvider>
    </AuthProvider>
  );
}
